    async generateUserStoriesReport(format, reportType = 'detailed') {
        try {
            // Load all teams
            const teamsQuery = query(collection(window.firebaseDb, 'projectGroups'));
            const teamsSnapshot = await getDocs(teamsQuery);
            
            const teamsStatus = [];
            
            for (const teamDoc of teamsSnapshot.docs) {
                const teamData = teamDoc.data();
                const teamId = teamDoc.id;
                
                // Load user stories
                const storiesQuery = query(
                    collection(window.firebaseDb, 'userStories'),
                    where('teamId', '==', teamId)
                );
                const storiesSnapshot = await getDocs(storiesQuery);
                
                const stories = [];
                storiesSnapshot.forEach(doc => {
                    stories.push({ id: doc.id, ...doc.data() });
                });
                
                // Load planning data (submission/verification status)
                const planningDoc = await getDoc(doc(window.firebaseDb, 'projectPlanning', teamId));
                const planningData = planningDoc.exists() ? planningDoc.data() : null;
                
                const isSubmitted = planningData && planningData.userStoriesSubmitted === true;
                const isVerified = planningData && planningData.userStoriesVerified === true;
                const verificationStatus = planningData ? planningData.userStoriesVerificationStatus : null;
                
                // Get guide name if available
                let guideName = 'N/A';
                if (teamData.guideId) {
                    try {
                        const guideDoc = await getDoc(doc(window.firebaseDb, 'users', teamData.guideId));
                        if (guideDoc.exists()) {
                            guideName = guideDoc.data().name || 'Unknown Guide';
                        }
                    } catch (e) {
                        console.warn('Error loading guide name:', e);
                    }
                }
                
                // Check if there are new stories added after verification or if any approved stories were revoked
                let hasNewStoriesAfterVerification = false;
                let hasRevokedApprovals = false;
                if (isVerified && verificationStatus && verificationStatus.verifiedAt) {
                    const verifiedAt = verificationStatus.verifiedAt.toDate ? verificationStatus.verifiedAt.toDate().getTime() : 0;
                    stories.forEach(story => {
                        const storyCreatedAt = story.createdAt?.toDate ? story.createdAt.toDate().getTime() : 0;
                        if (storyCreatedAt > verifiedAt) {
                            hasNewStoriesAfterVerification = true;
                        }
                        // Check if story was previously approved but is now pending
                        if (!story.approved && !story.rejected && story.createdAt?.toDate && story.createdAt.toDate().getTime() <= verifiedAt) {
                            hasRevokedApprovals = true;
                        }
                    });
                }
                
                // Only load user names for stories if detailed report is needed
                if (reportType === 'detailed') {
                const usersQuery = query(
                    collection(window.firebaseDb, 'projectUsers'),
                    where('teamId', '==', teamId)
                );
                const usersSnapshot = await getDocs(usersQuery);
                const usersMap = {};
                usersSnapshot.forEach(doc => {
                    usersMap[doc.id] = doc.data().name || 'Unknown';
                });
                
                // Add user names to stories
                stories.forEach(story => {
                    story.userName = usersMap[story.userId] || 'Unknown';
                });
                }
                
                teamsStatus.push({
                    teamId: teamId,
                    teamName: teamData.groupName || 'Unknown Team',
                    guideName: guideName,
                    stories: stories,
                    storiesCount: stories.length,
                    isSubmitted: isSubmitted,
                    isVerified: isVerified && !hasNewStoriesAfterVerification && !hasRevokedApprovals,
                    needsReverification: isVerified && (hasNewStoriesAfterVerification || hasRevokedApprovals),
                    verificationStatus: verificationStatus
                });
            }
            
            // Filter out test teams (case-insensitive)
            const filteredTeamsStatus = teamsStatus.filter(team => {
                const teamNameLower = (team.teamName || '').toLowerCase();
                return !teamNameLower.includes('test');
            });
            
            // Sort by team order settings
            const sortedTeamsStatus = await this.applyTeamOrderToReports(filteredTeamsStatus);
            
            // Generate based on format
            if (format === 'csv') {
                this.generateUserStoriesCSVReport(sortedTeamsStatus, reportType);
            } else if (format === 'json') {
                this.generateUserStoriesJSONReport(sortedTeamsStatus, reportType);
            } else {
                // For PDF/HTML/DOCX, generate HTML report
                const reportContent = reportType === 'minimal' 
                    ? this.generateUserStoriesMinimalReportContent(sortedTeamsStatus)
                    : this.generateUserStoriesReportContent(sortedTeamsStatus);
                
                const reportName = reportType === 'minimal' 
                    ? 'User Stories Status Report (Minimal)'
                    : 'User Stories Submission Status Report';
                
                if (format === 'pdf') {
                    await this.generatePDFReport(reportContent, { groupName: 'User Stories Status' }, { name: reportName });
                } else if (format === 'html') {
                    this.generateHTMLReport(reportContent, { groupName: 'User Stories Status' }, { name: reportName });
                } else if (format === 'docx') {
                    await this.generateDOCXReport(reportContent, { groupName: 'User Stories Status' }, { name: reportName });
                }
            }
        } catch (error) {
            console.error('Error generating user stories report:', error);
            throw error;
        }
    },
    
